    }
}
'''

##### 正确示例
'''php
class MyClass {
    private function myPrivateMethod() {
        return 42;
    }

    public function publicMethod() {
        return $this->myPrivateMethod(); // 正确：在类内部访问私有方法
    }
}

$instance = new MyClass();
$result = $instance->publicMethod(); // 通过公共方法访问私有方法
'''

rules.content_en:
